// Mô phỏng ý tưởng của 'use cache' + cacheLife + cacheTag bằng một bộ nhớ đệm nhỏ
let clock = 0;                      // đồng hồ giả để thử nghiệm
const store = new Map();

function cached(key, fn, { ttl, tags = [] }) {
  const hit = store.get(key);
  if (hit && clock - hit.at < ttl) return hit.value;       // còn hạn: trả cache
  const value = fn();                                      // hết hạn/chưa có: tính lại
  store.set(key, { value, at: clock, tags });
  return value;
}

function revalidateTag(tag) {
  for (const [k, v] of store) if (v.tags.includes(tag)) store.delete(k);
}

let calls = 0;
const getProducts = () => cached("products", () => ++calls, { ttl: 60, tags: ["products"] });

console.log(getProducts(), getProducts());   // 1 1  (lần hai từ cache)
clock = 61;
console.log(getProducts());                  // 2    (hết hạn)
revalidateTag("products");
console.log(getProducts());                  // 3    (bị làm mới theo thẻ)

